//IMG:/Users/dioscorid/Projects/C/presets/textures/Images/4.jpg
// =========================================================================
// Title: Drifting Image  (matrice IDENTITA' + traslazione)
//
// Famiglia "Animated Images": l'immagine caricata (ambito "All") viene
// campionata via iChannel0 e trasformata da una matrice 2x2 che dipende dal
// tempo. La matrice agisce sulle COORDINATE del piano della texture, percio'
// e' 2x2: mappa (x,y) in (x',y').
//
// DUE VINCOLI DEL RAMO SHADERTOY di questo motore:
//  1. gli slider A..F e t NON sono usabili qui: il motore li dichiara come
//     variabili LOCALI di getCustomColor(), mentre mainImage() e' una
//     funzione a se' -> "'A' : undeclared identifier";
//  2. niente dichiarazioni a livello di MODULO (const, funzioni, #define):
//     con due mesh che usano questo script il fragment ne conterrebbe due
//     copie -> "redefinition", e la superficie sparirebbe.
// Percio' i parametri stanno DENTRO mainImage: li' lo scope e' per-funzione
// e ogni mesh ha la sua copia.
// =========================================================================
//
// MATRICE IDENTITA': non deforma nulla -- e' la trasformazione neutra, e da
// sola l'immagine resterebbe FERMA. Qui serve da base: l'animazione viene da
// una traslazione che scorre nel tempo, quindi l'immagine si muove restando
// perfettamente intatta (nessuno stiramento, nessuna rotazione).
// E' anche il punto di partenza piu' comodo per scrivere una variante propria:
// si sostituisce la matrice identita' con quella che si vuole.

void mainImage(out vec4 Q, vec2 U)
{
    // --- PARAMETRI (modificabili qui) ---
    float speed = 0.15;   // velocita' dello scorrimento
    float amount = 0.25;  // ampiezza dello spostamento (in frazioni di immagine)

    // Coordinata centrata: nel ramo Shadertoy iResolution vale 1024,
    // quindi V va circa in [-0.5, 0.5].
    vec2 V = U / iResolution.xy - 0.5;

    // Matrice IDENTITA': lascia le coordinate come sono.
    mat2 M = mat2(1.0, 0.0,
                  0.0, 1.0);
    V = M * V;

    // L'animazione e' tutta qui: uno scorrimento circolare.
    float a = iTime * speed;
    V += amount * vec2(cos(a), sin(a));

    // Campionamento diretto, senza bias di mip: l'immagine resta nitida.
    // +0.5 riporta la coordinata in [0,1].
    Q = texture(iChannel0, V + 0.5);
}

